"""SQLAlchemy foundation shared by every model.

Provides:

* ``Base``: the declarative base class all models inherit from. Its metadata
  carries a naming convention, so every constraint and index gets the
  predictable name documented in docs/database.md (``uq_tasks_project_id_number``,
  ``fk_tasks_status_id_task_statuses``, ...). Alembic migrations rely on these
  names to alter or drop constraints later.
* ``BigIntPK``: the standard primary key, ``BIGINT GENERATED BY DEFAULT AS IDENTITY``.
* ``CreatedAtMixin`` / ``TimestampMixin``: ``created_at`` / ``updated_at`` columns
  as ``TIMESTAMPTZ`` (P-1), filled in by PostgreSQL.

Model files import from here; this file imports no models.
"""

from datetime import datetime
from typing import Annotated, Any, ClassVar

from sqlalchemy import BigInteger, DateTime, Identity, MetaData, func, inspect
from sqlalchemy.ext.asyncio import AsyncAttrs
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

# Constraint and index names (docs/database.md, section 1).
# column_0_N_name joins every column name with "_", e.g. uq_tasks_project_id_number.
NAMING_CONVENTION: dict[str, str] = {
    "pk": "pk_%(table_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    # Check constraints must be given a short name, e.g. name="status" -> ck_projects_status
    "ck": "ck_%(table_name)s_%(constraint_name)s",
}


class Base(AsyncAttrs, DeclarativeBase):
    """Base class for all models.

    * ``AsyncAttrs`` adds ``await obj.awaitable_attrs.<relationship>`` for the rare
      case where a relationship must be loaded after the query (normally we load
      relationships up front with selectinload / joinedload).
    * ``eager_defaults`` makes INSERT and UPDATE return server-generated values
      (``id``, ``created_at``, ``updated_at``) via ``RETURNING`` in the same round
      trip. Without it, reading ``obj.updated_at`` after an update would trigger a
      hidden extra query, which fails under AsyncSession.
    """

    metadata = MetaData(naming_convention=NAMING_CONVENTION)

    type_annotation_map: ClassVar[dict[Any, Any]] = {
        datetime: DateTime(timezone=True),  # every datetime column is TIMESTAMPTZ
    }

    __mapper_args__: ClassVar[dict[str, Any]] = {"eager_defaults": True}

    def __repr__(self) -> str:
        # Only the primary key: a repr must never print password hashes or tokens.
        identity = inspect(self).identity
        key = ", ".join(str(part) for part in identity) if identity else "transient"
        return f"<{type(self).__name__} {key}>"


# Standard surrogate primary key: BIGINT GENERATED BY DEFAULT AS IDENTITY.
BigIntPK = Annotated[
    int,
    mapped_column(BigInteger, Identity(always=False), primary_key=True),
]


class CreatedAtMixin:
    """``created_at`` only. For team_members and the two token tables (docs/database.md)."""

    created_at: Mapped[datetime] = mapped_column(
        server_default=func.now(),
        nullable=False,
        sort_order=900,  # keep timestamps as the last columns in CREATE TABLE
    )


class TimestampMixin(CreatedAtMixin):
    """``created_at`` and ``updated_at``.

    ``updated_at`` is refreshed on every ORM update with ``statement_timestamp()``:
    the time the UPDATE statement started. (``now()`` would be the time the whole
    transaction started, which can be earlier than a change another user already
    committed, making ``updated_at`` appear to move backwards.)

    Bulk ``update()`` statements don't run ``onupdate``; they must set
    ``updated_at=func.statement_timestamp()`` themselves (docs/database.md, section 1).
    """

    updated_at: Mapped[datetime] = mapped_column(
        server_default=func.now(),
        onupdate=func.statement_timestamp(),
        nullable=False,
        sort_order=901,
    )
